	/**
	 * Default Constructor
	 */
    public TradeOrderService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TradeOrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TradeOrderRepository.class) );
		this.validator		= applicationContext.getBean(TradeOrderValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TradeOrder
	 */
		public TradeOrder createTradeOrder( CreateTradeOrderCommand command ) {

		TradeOrder entity = new TradeOrder();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTradeOrderId( command.getTradeOrderId() );
            entity.setOrderId( command.getOrderId() );
            entity.setQuantity( command.getQuantity() );
            entity.setLimitPrice( command.getLimitPrice() );
            entity.setPlacedAt( command.getPlacedAt() );
            entity.setSide( command.getSide() );
            entity.setType( command.getType() );
            entity.setStatus( command.getStatus() );
            entity.setTimeInForce( command.getTimeInForce() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TradeOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTradeOrderCommand
	 * @return		TradeOrder
	 */
	public TradeOrder updateTradeOrder( UpdateTradeOrderCommand command ) {

		TradeOrder entity = new TradeOrder();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTradeOrderId( command.getTradeOrderId() );
            entity.setOrderId( command.getOrderId() );
            entity.setQuantity( command.getQuantity() );
            entity.setLimitPrice( command.getLimitPrice() );
            entity.setPlacedAt( command.getPlacedAt() );
            entity.setPortfolio( command.getPortfolio() );
            entity.setSecurity( command.getSecurity() );
            entity.setTrades( command.getTrades() );
            entity.setSide( command.getSide() );
            entity.setType( command.getType() );
            entity.setStatus( command.getStatus() );
            entity.setTimeInForce( command.getTimeInForce() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of TradeOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTradeOrderCommand
	 */
	public void delete( DeleteTradeOrderCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTradeOrderId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of TradeOrder {0} ", id );

	}

	/**
	 * Method to retrieve the TradeOrder via TradeOrderFetchOneSummary
	 * @param 	summary TradeOrderFetchOneSummary
	 * @return 	TradeOrderFetchOneResponse
	 */
	public TradeOrder getTradeOrder( TradeOrderFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TradeOrderFetchOneSummary arg cannot be null" );

		TradeOrder entity = null;
		UUID id = summary.getTradeOrderId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TradeOrder using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all TradeOrders
	 *
	 * @return 	List<TradeOrder>
	 */
    public List<TradeOrder> getAllTradeOrder() {
		List<TradeOrder> list = projector.findAll( new FindAllTradeOrderQuery() );
		return list;
	}

	/**
	 * assign Portfolio on TradeOrder
	 * @param		command AssignPortfolioToTradeOrderCommand
	 */
	public void assignPortfolio( AssignPortfolioToTradeOrderCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPortfolio(command.getTradeOrderId(), command.getAssignment());

	}

